	/// <summary>One REST request, ready for a transport to send.</summary>
	public sealed class RestRequest
	{
		public RestRequest(string method, string path, string? body, string? contentType)
		{
			Method = method;
			Path = path;
			Body = body;
			ContentType = contentType;
		}

		/// <summary>The HTTP method, upper case.</summary>
		public string Method { get; }

		/// <summary>The path and query, relative to the API base URL.</summary>
		public string Path { get; }

		/// <summary>The encoded request body, or null when the operation sends none.</summary>
		public string? Body { get; }

		/// <summary>The body's media type, or null when there is no body.</summary>
		public string? ContentType { get; }
	}

	/// <summary>
	/// The hand-written half of the REST client: base URL, authentication, and
	/// the HTTP stack. Unity, Godot .NET, and a plain .NET host each have a
	/// different one, which is why it is injected rather than named.
	/// </summary>
	public interface IRestApiTransport
	{
		/// <summary>
		/// Sends the request and returns the response body text, or null for an
		/// empty response. A non-2xx response must surface as an exception: the
		/// generated operations only decode success bodies.
		/// </summary>
		Task<string?> SendAsync(RestRequest request, CancellationToken cancellationToken);

		/// <summary>The absolute URL for a path a browser navigates to rather than fetches.</summary>
		Uri Url(string path);
	}

	internal static class RestPath
	{
		public static string Build(
			string template,
			(string Name, object? Value)[] pathValues,
			(string Name, object? Value)[] queryValues)
		{
			var path = template;
			foreach (var (name, value) in pathValues)
				path = path.Replace("{" + name + "}", Uri.EscapeDataString(Format(value)));

			var query = new List<string>();
			foreach (var (name, raw) in queryValues)
			{
				if (raw is null) continue;
				if (raw is IEnumerable enumerable && !(raw is string))
				{
					foreach (var value in enumerable)
					{
						if (value is null) continue;
						query.Add(Uri.EscapeDataString(name) + "=" + Uri.EscapeDataString(Format(value)));
					}
					continue;
				}
				query.Add(Uri.EscapeDataString(name) + "=" + Uri.EscapeDataString(Format(raw)));
			}

			return query.Count == 0 ? path : path + "?" + string.Join("&", query);
		}

		internal static string Format(object? value)
		{
			switch (value)
			{
				case null: return "";
				case bool flag: return flag ? "true" : "false";
				case IFormattable formattable: return formattable.ToString(null, CultureInfo.InvariantCulture);
				default: return value.ToString() ?? "";
			}
		}
	}

	internal static class RestForm
	{
		/// <summary>Form-encodes the top-level members of a request DTO, from its JSON.</summary>
		public static string Encode(string json, IHaivenJsonCodec codec)
		{
			var fields = new List<string>();
			foreach (var member in codec.Parse(json).EnumerateObject())
			{
				if (member.Value.Kind == HaivenJsonKind.Null) continue;
				var text = member.Value.Kind == HaivenJsonKind.String
					? member.Value.GetString()
					: member.Value.ToJson();
				fields.Add(Uri.EscapeDataString(member.Key) + "=" + Uri.EscapeDataString(text));
			}
			return string.Join("&", fields);
		}
	}

	/// <summary>Typed operations layered over an injected <see cref="IRestApiTransport"/>.</summary>
	public sealed class RestApi
	{
		private readonly IRestApiTransport transport;
		private readonly IHaivenJsonCodec codec;

		public RestApi(IRestApiTransport transport)
			: this(transport, null)
		{
		}

		/// <summary>A client over a specific JSON codec; <c>null</c> means <see cref="HaivenJson.Default"/>.</summary>
		public RestApi(IRestApiTransport transport, IHaivenJsonCodec? codec)
		{
			this.transport = transport ?? throw new ArgumentNullException(nameof(transport));
			this.codec = codec ?? HaivenJson.Default;
		}

		/// <summary>The JSON codec this client reads and writes bodies with.</summary>
		public IHaivenJsonCodec Codec => codec;

		private string Serialize(Action<IHaivenJsonWriter> write) => codec.Write(write);

		private T Read<T>(string? text, Func<IHaivenJsonNode, string, T> read)
		{
			if (string.IsNullOrEmpty(text)) return default!;
			var node = codec.Parse(text!);
			return node.Kind == HaivenJsonKind.Null ? default! : read(node, "response");
		}

