		{
			var requestPath = RestPath.Build("/users/me/sign-in-methods/sso/{provider}", new (string, object?)[] { ("provider", (object?)provider) }, Array.Empty<(string, object?)>());
			var responseText = await transport.SendAsync(new RestRequest("POST", requestPath, null, null), cancellationToken).ConfigureAwait(false);
			return Read(responseText, (node, path) => RestJson.ReadStartFederatedLinkResponse(node, path));
		}

